// Target-egress preflight check
const requiredEnv = ['SPIDER_API_KEY', 'WEBSHARE_PROXY_URL', 'HARVY_RAW', 'HARVY_ARTIFACTS'];
const missing = requiredEnv.filter(env => !process.env[env]);

if (missing.length > 0) {
  throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
}

// Set backfill cursor and forward watermark
const now = new Date();
const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const backfillCursor = oneWeekAgo.toISOString();
const forwardWatermark = now.toISOString();

return [{
  json: {
    source_id: 'usgs-earthquakes-bulk',
    idempotency_key: `usgs-${now.getTime()}-${Math.random().toString(36).substr(2, 9)}`,
    backfill_cursor: backfillCursor,
    forward_watermark: forwardWatermark,
    provenance: {
      source: 'USGS Earthquake API',
      url: 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_week.geojson',
      license: 'Public Domain',
      retrieved_at: now.toISOString(),
      data_shape: 'GeoJSON FeatureCollection'
    },
    scope: {
      tenant_id: '{{ $json.organization_id }}',
      product_id: 'harvy-ingestion',
      environment: 'production'
    }
  }
}];

// Error logging to harvy_errors
const error = items[0].json.error || null;
const runId = items[0].json.run_id || 'unknown';

if (error) {
  console.error(`[USGS Ingestion Error] Run ${runId}:`, error);
  // Log to OpenObserve via HTTP
  try {
    await fetch('https://eu1-api.openobserve.ai/api/default/harvy-logs/_json', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${process.env.OPENOBSERVE_TOKEN}`
      },
      body: JSON.stringify({
        timestamp: new Date().toISOString(),
        level: 'error',
        service: 'usgs-earthquakes-ingestion',
        run_id: runId,
        message: error.message,
        stack: error.stack,
        source: 'n8n-workflow'
      })
    });
  } catch (logError) {
    console.error('Failed to log to OpenObserve:', logError.message);
  }

  return [];
}

return items;

// Deterministic event_id generation
const crypto = require('crypto');

function generateDeterministicId(data, prefix = 'evt') {
  const hash = crypto.createHash('sha256');
  hash.update(JSON.stringify(data));
  return `${prefix}-${hash.digest('hex').substring(0, 16)}`;
}

const eventData = {
  source_id: 'usgs-earthquakes-bulk',
  timestamp: new Date().toISOString(),
  organization_id: items[0].json.organization_id,
  run_id: items[0].json.run_id
};

return [{
  json: {
    ...items[0].json,
    event_id: generateDeterministicId(eventData),
    deduplication_key: `usgs-${items[0].json.run_id}`
  }
}];

// Deduplication check against harvy_errors
const crypto = require('crypto');

function calculateHash(data) {
  return crypto.createHash('sha256').update(JSON.stringify(data)).digest('hex');
}

const existingHashes = []; // Would query harvy_errors in production

const uniqueItems = items.filter(item => {
  const itemHash = calculateHash(item.json);
  if (existingHashes.includes(itemHash)) {
    console.log(`Duplicate detected: ${item.json.id}`);
    return false;
  }
  return true;
});

if (uniqueItems.length !== items.length) {
  console.log(`Deduplicated ${items.length - uniqueItems.length} items`);
}

return uniqueItems;

